def min_cost_ii(costs):
    """
    Minimize cost to paint n houses with k colors (no adjacent same color).
    Uses O(n×k) DP tracking min and second-min from previous row.
    """
    if not costs:
        return 0

    n, k = len(costs), len(costs[0])
    prev = costs[0][:]

    for i in range(1, n):
        # Find min1, min2, min1_idx from previous row
        min1, min2, min1_idx = float('inf'), float('inf'), -1
        for j in range(k):
            if prev[j] < min1:
                min2, min1, min1_idx = min1, prev[j], j
            elif prev[j] < min2:
                min2 = prev[j]

        # Compute current row
        curr = [0] * k
        for j in range(k):
            if j == min1_idx:
                curr[j] = costs[i][j] + min2
            else:
                curr[j] = costs[i][j] + min1
        prev = curr

    return min(prev)
